pub fn min_stones_to_remove(colors: Vec<u8>, n: usize) -> usize {
    let mut stones_to_remove = 0;
    let mut i = 0;
    while i < n - 1 {
        if colors[i] == colors[i + 1] {
            stones_to_remove += 1;
            i += 2;
        } else {
            i += 1;
        }
    }
    stones_to_remove
}
